import{_ as t,o as n,c as a,a2 as r}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"Wie lösche ich Geräte und räume alte Datenpunkte auf?","description":"","frontmatter":{"order":2,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/02.anleitungen/02.geraete-verwalten.md"},"headers":[],"relativePath":"de/adapter/esphome/anleitungen/geraete-verwalten.md","filePath":"de/adapter/esphome/anleitungen/geraete-verwalten.md","lastUpdated":null}'),i={name:"de/adapter/esphome/anleitungen/geraete-verwalten.md"};function d(s,e,c,o,l,h){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="wie-losche-ich-gerate-und-raume-alte-datenpunkte-auf" tabindex="-1">Wie lösche ich Geräte und räume alte Datenpunkte auf? <a class="header-anchor" href="#wie-losche-ich-gerate-und-raume-alte-datenpunkte-auf" aria-label="Permalink to &quot;Wie lösche ich Geräte und räume alte Datenpunkte auf?&quot;">​</a></h1><p><a id="delete-device-completely-objects-come"></a></p><h2 id="wie-losche-ich-ein-gerat-komplett-und-warum-kommen-die-objekte-zuruck" tabindex="-1">Wie lösche ich ein Gerät komplett und warum kommen die Objekte zurück? <a class="header-anchor" href="#wie-losche-ich-ein-gerat-komplett-und-warum-kommen-die-objekte-zuruck" aria-label="Permalink to &quot;Wie lösche ich ein Gerät komplett und warum kommen die Objekte zurück?&quot;">​</a></h2><p>Lösch ein Gerät immer im Reiter „Geräte“: beim Gerät auf „Gerät löschen“ und die Rückfrage bestätigen. Der Adapter trennt dann die Verbindung und löscht das Gerät mit allen Datenpunkten. Das lässt sich nicht rückgängig machen.</p><p>Löschst du stattdessen nur die Objekte im Tab „Objekte“, bleibt das Gerät im laufenden Adapter verbunden. Bei der nächsten Verbindung legt er die Objekte wieder an.</p><p>Läuft das Gerät nach dem Löschen weiter, findet die Erkennung es wieder. Es steht dann in „Gefunden, noch nicht hinzugefügt“, ohne Datenpunkte. Soll es dort nicht mehr erscheinen, schalte es aus oder trag seine Adresse in die Ausschlussliste der Erkennung ein.</p><p><strong>Siehe auch:</strong> <a href="./geraete-entdecken#auto-discovery-report-routers-foreign">Adresse von der Erkennung ausschließen</a> · <a href="#clean-up-devices-datapoints-no">Alte Geräte aufräumen</a></p><p><a id="clean-up-devices-datapoints-no"></a></p><h2 id="wie-raume-ich-nicht-mehr-vorhandene-gerate-und-alte-datenpunkte-auf" tabindex="-1">Wie räume ich nicht mehr vorhandene Geräte und alte Datenpunkte auf? <a class="header-anchor" href="#wie-raume-ich-nicht-mehr-vorhandene-gerate-und-alte-datenpunkte-auf" aria-label="Permalink to &quot;Wie räume ich nicht mehr vorhandene Geräte und alte Datenpunkte auf?&quot;">​</a></h2><p>Der Adapter räumt auf zwei Wegen auf.</p><p><strong>Automatisch:</strong> 10 Sekunden nachdem ein Gerät verbunden ist, löscht der Adapter unter diesem Gerät alle Ordner, die das Gerät nicht mehr meldet, z. B. nach dem Entfernen einer Entität aus der YAML. Einzelne Datenpunkte in noch gemeldeten Ordnern bleiben stehen. Die löschst du bei Bedarf im Tab „Objekte“.</p><p><strong>Von Hand:</strong> Der Datenpunkt <code>esphome.0.info.deviceCleanup</code> löscht alle Geräte, deren <code>info._online</code> gerade <code>false</code> ist, mit allen Datenpunkten. Setz ihn im Tab „Objekte“ auf <code>true</code>.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><code>info.deviceCleanup</code> fragt nicht nach. Es löscht auch Geräte, die nur kurz offline sind, samt Datenpunkten und gespeicherten Zugangsdaten.</p></div><p>Kommt ein so gelöschtes Gerät wieder online, solange die Instanz läuft, legt der Adapter es neu an. Willst du ein einzelnes Gerät dauerhaft loswerden, lösch es im Reiter „Geräte“.</p><p><strong>Siehe auch:</strong> <a href="#delete-device-completely-objects-come">Gerät komplett löschen</a></p><p><a id="recover-stored-masked-api-password"></a></p><h2 id="wie-finde-ich-das-gespeicherte-maskierte-api-passwort-oder-den-schlussel-wieder" tabindex="-1">Wie finde ich das gespeicherte (maskierte) API-Passwort oder den Schlüssel wieder? <a class="header-anchor" href="#wie-finde-ich-das-gespeicherte-maskierte-api-passwort-oder-den-schlussel-wieder" aria-label="Permalink to &quot;Wie finde ich das gespeicherte (maskierte) API-Passwort oder den Schlüssel wieder?&quot;">​</a></h2><p>Der Adapter speichert Schlüssel und API-Passwort verschlüsselt im Geräteobjekt und zeigt sie nicht wieder an. Im Dialog „Verbindungseinstellungen ändern“ sind die Felder deshalb leer. Lässt du beide leer, behält der Adapter die gespeicherten Werte.</p><p>Den Schlüssel findest du in der YAML des Geräts unter <code>api:</code> → <code>encryption:</code> → <code>key:</code>, oder in der <code>secrets.yaml</code>, wenn die YAML ihn mit <code>!secret</code> einbindet. Beide Dateien öffnest du im Dashboard oder im Reiter „YAML-Dateien“ mit „In Editor öffnen“. Ein OTA-Passwort speichert der Adapter nicht.</p><p><strong>Siehe auch:</strong> <a href="./yaml-dateien#upload-view-delete-yaml-files">YAML-Dateien ansehen</a></p>',20)])])}const m=t(i,[["render",d]]);export{p as __pageData,m as default};
